CREATE TABLE public.game_night_polls (trip_id uuid PRIMARY KEY REFERENCES public.trips(id) ON DELETE CASCADE, options jsonb NOT NULL CHECK (jsonb_typeof(options)='array' AND jsonb_array_length(options) BETWEEN 3 AND 5), confirmed_option integer, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.game_night_polls TO authenticated; GRANT ALL ON public.game_night_polls TO service_role;
ALTER TABLE public.game_night_polls ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Members view poll" ON public.game_night_polls FOR SELECT TO authenticated USING (trip_private.is_trip_member(trip_id,auth.uid()));
CREATE POLICY "Captain creates poll" ON public.game_night_polls FOR INSERT TO authenticated WITH CHECK (EXISTS (SELECT 1 FROM public.trip_members m WHERE m.trip_id=game_night_polls.trip_id AND m.user_id=auth.uid() AND m.role='captain'));
CREATE POLICY "Captain edits poll" ON public.game_night_polls FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM public.trip_members m WHERE m.trip_id=game_night_polls.trip_id AND m.user_id=auth.uid() AND m.role='captain')) WITH CHECK (EXISTS (SELECT 1 FROM public.trip_members m WHERE m.trip_id=game_night_polls.trip_id AND m.user_id=auth.uid() AND m.role='captain'));
CREATE TRIGGER set_game_night_polls_updated_at BEFORE UPDATE ON public.game_night_polls FOR EACH ROW EXECUTE FUNCTION public.set_trip_updated_at();
CREATE TABLE public.game_night_votes (trip_id uuid NOT NULL REFERENCES public.trips(id) ON DELETE CASCADE, user_id uuid NOT NULL, option_index integer NOT NULL CHECK (option_index BETWEEN 0 AND 4), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(trip_id,user_id,option_index), FOREIGN KEY(trip_id) REFERENCES public.game_night_polls(trip_id) ON DELETE CASCADE);
GRANT SELECT, INSERT, DELETE ON public.game_night_votes TO authenticated; GRANT ALL ON public.game_night_votes TO service_role;
ALTER TABLE public.game_night_votes ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Members view votes" ON public.game_night_votes FOR SELECT TO authenticated USING (trip_private.is_trip_member(trip_id,auth.uid()));
CREATE POLICY "Members vote" ON public.game_night_votes FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid() AND trip_private.is_trip_member(trip_id,auth.uid()) AND EXISTS (SELECT 1 FROM public.game_night_polls p WHERE p.trip_id=game_night_votes.trip_id AND p.confirmed_option IS NULL AND option_index < jsonb_array_length(p.options)));
CREATE POLICY "Members remove vote" ON public.game_night_votes FOR DELETE TO authenticated USING (user_id=auth.uid() AND EXISTS (SELECT 1 FROM public.game_night_polls p WHERE p.trip_id=game_night_votes.trip_id AND p.confirmed_option IS NULL));
CREATE TABLE public.game_nights (trip_id uuid NOT NULL REFERENCES public.trips(id) ON DELETE CASCADE, week_number integer NOT NULL CHECK (week_number BETWEEN 1 AND 104), starts_at timestamptz NOT NULL, host_id uuid NOT NULL, game_number integer CHECK (game_number BETWEEN 1 AND 12), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(trip_id,week_number), FOREIGN KEY (trip_id,host_id) REFERENCES public.trip_members(trip_id,user_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.game_nights TO authenticated; GRANT ALL ON public.game_nights TO service_role;
ALTER TABLE public.game_nights ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Members view nights" ON public.game_nights FOR SELECT TO authenticated USING (trip_private.is_trip_member(trip_id,auth.uid()));
CREATE TRIGGER set_game_nights_updated_at BEFORE UPDATE ON public.game_nights FOR EACH ROW EXECUTE FUNCTION public.set_trip_updated_at();
CREATE TABLE public.game_catalog (number integer PRIMARY KEY CHECK (number BETWEEN 1 AND 12), name text NOT NULL, how_to_play text NOT NULL, twist text NOT NULL, how_to_win text NOT NULL, prep text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.game_catalog TO authenticated; GRANT ALL ON public.game_catalog TO service_role;
ALTER TABLE public.game_catalog ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Signed in see games" ON public.game_catalog FOR SELECT TO authenticated USING (true);
INSERT INTO public.game_catalog(number,name,how_to_play,twist,how_to_win,prep) VALUES
(1,'Two Truths and a Trip','Say two truths and one lie. Everyone calls out the lie.','Tell the story behind a truth.','Most correct guesses.','None.'),
(2,'Baby Pic: Guess the Age','Screen-share a baby or kid photo and share a memory from that age. Everyone types an age guess.','What was your world like then?','Closest guess earns one point per photo; most points wins.','Have a childhood photo ready.'),
(3,'Whose Song Is It','Text the host two songs beforehand. The host plays clips; guess whose songs they are.','The owner explains why each song matters.','Most correct guesses.','Send the host two songs.'),
(4,'Hot Seat','Each person answers five questions from the deck. No skipping.','Ask one follow-up to get the real story.','Anonymous vote for best answers.','None.'),
(5,'Destination Trivia','The host reads trivia cards about the trip destination.','Share a surprising fact you learned.','Most correct answers.','Host opens destination cards.'),
(6,'Phrase of the Week','Learn three phrases in the destination language, or local slang for a domestic trip, and say them live.','Use one in a sentence about the trip.','Vote for best delivery.','Pick three phrases.'),
(7,'Cook-Off','Eat a dish inspired by the destination on the call.','Share a food that reminds you of home.','Group vote.','Bring a dish or snack.'),
(8,'Most Likely To','Read a prompt and vote live for the person most likely to do it.','The winner defends their title.','Most votes becomes legend of the week.','None.'),
(9,'Gartic Phone Night','The host shares a garticphone.com link. Draw and watch the chaos unfold.','Everyone narrates their favorite reveal.','Vote for funniest drawing.','Host opens garticphone.com.'),
(10,'Camera Roll Roulette','Draw a number. Everyone shows that numbered photo on camera, no skips, and tells its story.','What happened just before or after?','Vote for best story.','Have your camera roll ready.'),
(11,'Emoji Me','Text the host five emojis that describe you. Host screen-shares the sets; guess whose is whose.','Explain your five emojis.','Most correct guesses.','Send the host five emojis.'),
(12,'Would You Rather','Pick a destination-inspired dilemma quickly, then defend your choice.','Can anyone change your mind?','Vote for best defense.','None.');
CREATE TABLE public.game_cards (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, trip_id uuid REFERENCES public.trips(id) ON DELETE CASCADE, category text NOT NULL CHECK (category IN ('get-to-know','two-truths','childhood','songs','destination-trivia','phrases','most-likely','would-you-rather','camera-roll','emoji')), prompt text NOT NULL CHECK (length(prompt) BETWEEN 1 AND 500), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.game_cards TO authenticated; GRANT ALL ON public.game_cards TO service_role; GRANT USAGE, SELECT ON SEQUENCE public.game_cards_id_seq TO authenticated;
ALTER TABLE public.game_cards ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Members see cards" ON public.game_cards FOR SELECT TO authenticated USING (trip_id IS NULL OR trip_private.is_trip_member(trip_id,auth.uid()));
CREATE POLICY "Leaders add trip cards" ON public.game_cards FOR INSERT TO authenticated WITH CHECK (trip_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.trip_members m WHERE m.trip_id=game_cards.trip_id AND m.user_id=auth.uid() AND m.role IN ('captain','co_captain')));
