CREATE TABLE public.trip_play_state (trip_id uuid PRIMARY KEY REFERENCES public.trips(id) ON DELETE CASCADE, spin_game integer REFERENCES public.game_catalog(number), spin_week integer, spin_at timestamptz, draw_card_id bigint REFERENCES public.game_cards(id), draw_category text, draw_at timestamptz, used_games integer[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.trip_play_state TO authenticated; GRANT ALL ON public.trip_play_state TO service_role;
ALTER TABLE public.trip_play_state ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Members view play" ON public.trip_play_state FOR SELECT TO authenticated USING (trip_private.is_trip_member(trip_id,auth.uid()));
CREATE TRIGGER set_trip_play_state_updated_at BEFORE UPDATE ON public.trip_play_state FOR EACH ROW EXECUTE FUNCTION public.set_trip_updated_at();
CREATE OR REPLACE FUNCTION public.post_game_night_poll(p_trip uuid,p_options jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $fn$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid() AND role='captain') THEN RAISE EXCEPTION 'Only the Captain can post times'; END IF; IF jsonb_typeof(p_options)<>'array' OR jsonb_array_length(p_options) NOT BETWEEN 3 AND 5 OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(p_options) AS o(v) WHERE (v::timestamptz <= now() OR v::timestamptz >= (SELECT start_date FROM public.trips WHERE id=p_trip) OR length(v)>40)) THEN RAISE EXCEPTION 'Add 3 to 5 future times before the trip'; END IF; DELETE FROM public.game_night_polls WHERE trip_id=p_trip; INSERT INTO public.game_night_polls(trip_id,options) VALUES(p_trip,p_options); END $fn$;
CREATE OR REPLACE FUNCTION public.confirm_game_nights(p_trip uuid,p_option integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $fn$ DECLARE v_start timestamptz; v_end timestamptz; v_host uuid; v_count integer; BEGIN IF NOT EXISTS(SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid() AND role='captain') THEN RAISE EXCEPTION 'Only the Captain can confirm'; END IF; SELECT (options->>p_option)::timestamptz INTO v_start FROM public.game_night_polls WHERE trip_id=p_trip AND confirmed_option IS NULL; IF v_start IS NULL OR v_start <= now() THEN RAISE EXCEPTION 'Choose a future option'; END IF; SELECT start_date INTO v_end FROM public.trips WHERE id=p_trip; IF v_start >= v_end THEN RAISE EXCEPTION 'Time must be before the trip'; END IF; SELECT count(*) INTO v_count FROM public.trip_members WHERE trip_id=p_trip; DELETE FROM public.game_nights WHERE trip_id=p_trip; FOR i IN 1..104 LOOP EXIT WHEN v_start + ((i-1)* interval '7 days') >= v_end; SELECT user_id INTO v_host FROM public.trip_members WHERE trip_id=p_trip ORDER BY joined_at,user_id LIMIT 1 OFFSET ((i-1)%v_count); INSERT INTO public.game_nights(trip_id,week_number,starts_at,host_id) VALUES(p_trip,i,v_start + ((i-1)*interval '7 days'),v_host); END LOOP; UPDATE public.game_night_polls SET confirmed_option=p_option WHERE trip_id=p_trip; END $fn$;
CREATE OR REPLACE FUNCTION public.set_game_night_host(p_trip uuid,p_week integer,p_host uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $fn$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid() AND role='captain') THEN RAISE EXCEPTION 'Only the Captain can change hosts'; END IF; IF NOT EXISTS(SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=p_host) THEN RAISE EXCEPTION 'Choose a member of this trip'; END IF; UPDATE public.game_nights SET host_id=p_host WHERE trip_id=p_trip AND week_number=p_week; END $fn$;
CREATE OR REPLACE FUNCTION public.set_first_game(p_trip uuid,p_game integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $fn$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid() AND role='captain') THEN RAISE EXCEPTION 'Only the Captain can choose the first game'; END IF; UPDATE public.game_nights SET game_number=p_game WHERE trip_id=p_trip AND week_number=1 AND game_number IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'Week 1 already has a game or schedule is missing'; END IF; INSERT INTO public.trip_play_state(trip_id,used_games) VALUES(p_trip,ARRAY[p_game]) ON CONFLICT(trip_id) DO UPDATE SET used_games=array_append(array_remove(trip_play_state.used_games,p_game),p_game); END $fn$;
CREATE OR REPLACE FUNCTION public.spin_next_game(p_trip uuid) RETURNS TABLE(game_number integer,week_number integer,spin_time timestamptz) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $fn$ DECLARE v_week integer; v_game integer; v_used integer[]; v_now timestamptz := clock_timestamp(); BEGIN IF NOT EXISTS(SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid()) THEN RAISE EXCEPTION 'Not in this trip'; END IF; SELECT n.week_number INTO v_week FROM public.game_nights n WHERE n.trip_id=p_trip AND n.starts_at<=v_now ORDER BY n.starts_at DESC LIMIT 1; IF v_week IS NULL THEN RAISE EXCEPTION 'Wait for the first game night'; END IF; IF NOT EXISTS(SELECT 1 FROM public.trip_members m WHERE m.trip_id=p_trip AND m.user_id=auth.uid() AND (m.role IN ('captain','co_captain') OR m.user_id=(SELECT n.host_id FROM public.game_nights n WHERE n.trip_id=p_trip AND n.week_number=v_week))) THEN RAISE EXCEPTION 'Only a leader or this week''s host can spin'; END IF; IF NOT EXISTS(SELECT 1 FROM public.game_nights WHERE trip_id=p_trip AND week_number=v_week+1 AND game_number IS NULL) THEN RAISE EXCEPTION 'No unassigned next week'; END IF; INSERT INTO public.trip_play_state(trip_id) VALUES(p_trip) ON CONFLICT DO NOTHING; SELECT used_games INTO v_used FROM public.trip_play_state WHERE trip_id=p_trip FOR UPDATE; IF cardinality(v_used)>=12 THEN v_used:='{}'; END IF; SELECT number INTO v_game FROM public.game_catalog WHERE NOT(number=ANY(v_used)) ORDER BY random() LIMIT 1; UPDATE public.game_nights SET game_number=v_game WHERE trip_id=p_trip AND week_number=v_week+1; UPDATE public.trip_play_state SET used_games=array_append(v_used,v_game),spin_game=v_game,spin_week=v_week+1,spin_at=v_now WHERE trip_id=p_trip; RETURN QUERY SELECT v_game,v_week+1,v_now; END $fn$;
CREATE OR REPLACE FUNCTION public.draw_game_card(p_trip uuid,p_category text) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $fn$ DECLARE v_id bigint; BEGIN IF NOT EXISTS(SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid()) THEN RAISE EXCEPTION 'Not in this trip'; END IF; SELECT id INTO v_id FROM public.game_cards WHERE category=p_category AND (trip_id IS NULL OR trip_id=p_trip) ORDER BY random() LIMIT 1; IF v_id IS NULL THEN RAISE EXCEPTION 'No cards in this category'; END IF; INSERT INTO public.trip_play_state(trip_id,draw_card_id,draw_category,draw_at) VALUES(p_trip,v_id,p_category,clock_timestamp()) ON CONFLICT(trip_id) DO UPDATE SET draw_card_id=EXCLUDED.draw_card_id,draw_category=EXCLUDED.draw_category,draw_at=EXCLUDED.draw_at; RETURN v_id; END $fn$;
REVOKE ALL ON FUNCTION public.post_game_night_poll(uuid,jsonb),public.confirm_game_nights(uuid,integer),public.set_game_night_host(uuid,integer,uuid),public.set_first_game(uuid,integer),public.spin_next_game(uuid),public.draw_game_card(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.post_game_night_poll(uuid,jsonb),public.confirm_game_nights(uuid,integer),public.set_game_night_host(uuid,integer,uuid),public.set_first_game(uuid,integer),public.spin_next_game(uuid),public.draw_game_card(uuid,text) TO authenticated;
ALTER PUBLICATION supabase_realtime ADD TABLE public.game_night_polls,public.game_night_votes,public.game_nights,public.trip_play_state;